{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["header","directions-list"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"eyebrow":"Design directions","title":"Choose a look for your deck","subtitle":"Each direction is a full theme, with your title slide drawn in it."},"children":[]}}
{"op":"add","path":"/elements/directions-list","value":{"type":"Stack","props":{"direction":"vertical","gap":"none"},"repeat":{"statePath":"/result/directions"},"children":["direction-section"]}}
{"op":"add","path":"/elements/direction-section","value":{"type":"Section","props":{"title":{"$item":"theme/name"}},"children":["direction-split"]}}
{"op":"add","path":"/elements/direction-split","value":{"type":"Split","props":{"ratio":"2:1","gap":"xl"},"children":["mockup-picture","identity-rail"]}}
{"op":"add","path":"/elements/mockup-picture","value":{"type":"Picture","props":{"path":"mockup","aspect":"16:9","alt":"Title slide drawn in this direction's theme"},"children":[]}}
{"op":"add","path":"/elements/identity-rail","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["style-text","palette-swatches","typeface-detail","layout-detail","details-collapsible","avoids-detail"]}}
{"op":"add","path":"/elements/style-text","value":{"type":"Text","props":{"text":{"$item":"theme/style/overall"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/palette-swatches","value":{"type":"Swatches","props":{"colors":[{"$item":"theme/colors/primary"},{"$item":"theme/colors/secondary"},{"$item":"theme/colors/accent"},{"$item":"theme/colors/background"},{"$item":"theme/colors/text_primary"},{"$item":"theme/colors/text_secondary"}]},"children":[]}}
{"op":"add","path":"/elements/typeface-detail","value":{"type":"Detail","props":{"label":"Typeface","value":{"$item":"theme/typography/font_family"}},"children":[]}}
{"op":"add","path":"/elements/layout-detail","value":{"type":"Detail","props":{"label":"Layout","value":{"$template":"${theme/layout/aspect_ratio} · ${theme/layout/margins} margins · ${theme/layout/alignment}-aligned"}},"children":[]}}
{"op":"add","path":"/elements/details-collapsible","value":{"type":"Collapsible","props":{"title":"Type and style details","defaultOpen":false},"children":["headings-detail","body-detail","icons-detail","graphics-detail"]}}
{"op":"add","path":"/elements/headings-detail","value":{"type":"Detail","props":{"label":"Headings","value":{"$item":"theme/typography/heading_style"}},"children":[]}}
{"op":"add","path":"/elements/body-detail","value":{"type":"Detail","props":{"label":"Body text","value":{"$item":"theme/typography/body_style"}},"children":[]}}
{"op":"add","path":"/elements/icons-detail","value":{"type":"Detail","props":{"label":"Icons","value":{"$item":"theme/style/icon_style"}},"children":[]}}
{"op":"add","path":"/elements/graphics-detail","value":{"type":"Detail","props":{"label":"Graphics","value":{"$item":"theme/style/graphic_style"}},"children":[]}}
{"op":"add","path":"/elements/avoids-detail","value":{"type":"Detail","props":{"label":"Avoids","value":{"$item":"theme/exclusions"}},"children":[]}}
